  /** Validates input against inputSchema, returning a ToolResponse rejection on failure; see specs/hal-engine-tool-input-validation/spec.md. */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }

    const validator = this.getValidator(tool);
    const valid = validator(input);
    if (!valid) {
      const details = formatValidationErrors(validator.errors ?? []);
      const rejection = `Invalid input: ${details}`;
      log.warn('tool', 'input validation failed', {name, error: rejection});
      return {result: rejection};
    }

    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }

  private getValidator(tool: StoredTool): ValidateFunction {
    if (typeof tool.definitionSource === 'function') {
      return this.getDynamicValidator(tool.definitionSource);
    }
    return this.getStaticValidator(tool.definitionSource);
  }

  private getDynamicValidator(source: () => ToolDefinition): ValidateFunction {
    const definition = source();
    const cached = this.dynamicValidatorCache.get(definition.inputSchema);
    if (cached) {
      return cached;
    }
    const validator = this.compileSchema(definition.inputSchema, definition.name);
    this.dynamicValidatorCache.set(definition.inputSchema, validator);
    return validator;
  }

  private getStaticValidator(definition: ToolDefinition): ValidateFunction {
    const cached = this.staticValidators.get(definition.name);
    if (cached) {
      return cached;
    }
    const compiled = this.compileSchema(definition.inputSchema, definition.name);
    this.staticValidators.set(definition.name, compiled);
    return compiled;
  }
}

function formatValidationErrors(errors: ErrorObject[]): string {
  return errors.map(formatValidationError).join('; ');
}

function formatValidationError(err: ErrorObject): string {
  const dataPath = ((err.instancePath ?? (err as {dataPath?: string}).dataPath ?? '') as string)
    .replace(/^[\./]/, '')
    .replace(/\//g, '.');
  const missingProperty = typeof err.params?.missingProperty === 'string' ? err.params.missingProperty : undefined;
  if (err.keyword === 'required' && missingProperty) {
    const field = dataPath ? `${dataPath}.${missingProperty}` : missingProperty;
    return `missing required property '${field}'`;
  }
  if (dataPath) {
    return `property '${dataPath}' ${err.message ?? 'is invalid'}`;
  }
  return err.message ?? 'validation failed';
}

